&reftitle.description;

 publicYaf_Controller_AbstractnullYaf_Action_Abstract::getController



 Obtém o controlador ao qual esta ação pertence.

&reftitle.returnvalues;

 Uma instância de Yaf_Controller_Abstract, ou &null;
 se nenhum controlador estiver disponível.

  &reftitle.examples;

   Exemplo de Yaf_Action_Abstract::getController


<?php
class ListAction extends Yaf_Action_Abstract
{
    public function execute() {
        // o controlador ao qual esta ação pertence
        $controller = $this->getController();
        var_dump($controller instanceof Yaf_Controller_Abstract);

        // por exemplo, para acessar seu mecanismo de visualização
        $controller->getView()->assign("products", array("yaf", "php"));
    }
}
?>


